package com.wizzadrds.theworldremembers.dream; import com.mojang.serialization.Codec; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class DreamManager extends SavedData{private static final int MAX=128; private final Map<UUID,List<Dream>> dreams=new HashMap<>(); private static final Codec<DreamManager>C=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),Dream.CODEC.listOf()).xmap(m->{var x=new DreamManager();x.dreams.putAll(m);return x;},x->x.dreams); private static final SavedDataType<DreamManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","dreams"),DreamManager::new,C,null); public static DreamManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new DreamManager():l.getDataStorage().computeIfAbsent(TYPE);} public void add(Dream d){var list=dreams.computeIfAbsent(d.sleeper(),k->new ArrayList<>());list.add(d);while(list.size()>MAX)list.remove(0);setDirty();} public List<Dream> dreamsOf(UUID id){return List.copyOf(dreams.getOrDefault(id,List.of()));} public int total(){return dreams.values().stream().mapToInt(List::size).sum();}}
